export type RegistryModule = {
  name: string;
  hasModuleTs: boolean;
  hasEnv: boolean;
  hasAuth: boolean;
  hasAuthClient: boolean;
  hasAuditSink: boolean;
  hasEvents: boolean;
  hasSubscribers: boolean;
  hasSlots: boolean;
  hasClientSlots: boolean;
  locales: string[];
};

export const GENERATED_HEADER =
  "// generated by GatoJS — do not edit. Run: npm run wa -- generate";

function identifier(name: string, suffix: string): string {
  const camel = name.replace(/[-_.]+(.)/g, (_, char: string) =>
    char.toUpperCase(),
  );
  return `${camel}${suffix}`;
}

function array(items: string[]): string {
  return `[${items.join(", ")}]`;
}

export type RenderRegistryOptions = { hasGatoConfig: boolean };

const GATO_CONFIG_MODULE = "@/shared/lib/modules/gato-config";
const PROJECT_CONFIG_IMPORT = 'import gatoConfig from "@/gato.config";';
const EMPTY_CONFIG_IMPORT = `import { emptyGatoConfig as gatoConfig } from "${GATO_CONFIG_MODULE}";`;
const SLOTS_MODULE = "@/shared/lib/modules/slots";

type ConfigHelper =
  | "applyGatoConfig"
  | "enabledEntries"
  | "enabledModuleEntries"
  | "gatoBrandingOf";

function entry(module: RegistryModule, value: string): string {
  return `{ module: "${module.name}", value: ${value} }`;
}

function configuredModules(name: string, items: string[]): string {
  return items.length === 0
    ? `export const ${name}: never[] = [];`
    : `export const ${name} = applyGatoConfig(${array(items)}, gatoConfig);`;
}

function enabledList(name: string, entries: string[]): string {
  return entries.length === 0
    ? `export const ${name}: never[] = [];`
    : `export const ${name} = enabledEntries(${array(entries)}, gatoConfig);`;
}

function moduleEntries(name: string, entries: string[]): string {
  return entries.length === 0
    ? `export const ${name}: never[] = [];`
    : `export const ${name} = ${array(entries)};`;
}

function enabledModuleList(name: string, entries: string[]): string {
  return entries.length === 0
    ? `export const ${name}: never[] = [];`
    : `export const ${name} = enabledModuleEntries(${array(entries)}, gatoConfig);`;
}

function configImports(
  options: RenderRegistryOptions,
  helpers: ConfigHelper[],
): { config: string; helpers: string[] } {
  return {
    config: options.hasGatoConfig ? PROJECT_CONFIG_IMPORT : EMPTY_CONFIG_IMPORT,
    helpers:
      helpers.length === 0
        ? []
        : [`import { ${helpers.join(", ")} } from "${GATO_CONFIG_MODULE}";`],
  };
}

function slotsImport(module: RegistryModule): string {
  return `import * as ${identifier(module.name, "Slots")} from "@/features/${module.name}/slots";`;
}

function clientSlotsImport(module: RegistryModule): string {
  return `import * as ${identifier(module.name, "ClientSlots")} from "@/features/${module.name}/client-slots";`;
}

function slotEntries(modules: RegistryModule[], suffix: string): string {
  return array(modules.map((m) => entry(m, identifier(m.name, suffix))));
}

function usedHelpers(uses: Record<ConfigHelper, boolean>): ConfigHelper[] {
  const order: ConfigHelper[] = [
    "applyGatoConfig",
    "enabledEntries",
    "enabledModuleEntries",
    "gatoBrandingOf",
  ];
  return order.filter((helper) => uses[helper]);
}

export function renderLocales(locales: ("pl" | "en")[]): string {
  return `${GENERATED_HEADER}\nexport const locales = ${array(locales.map((l) => `"${l}"`))} as const;\n`;
}

export function renderRegistry(
  modules: RegistryModule[],
  locales: ("pl" | "en")[],
  options: RenderRegistryOptions = { hasGatoConfig: false },
): {
  server: string;
  client: string;
} {
  const withModule = modules.filter((m) => m.hasModuleTs);
  const withEnv = modules.filter((m) => m.hasEnv);
  const withAuth = modules.filter((m) => m.hasAuth);
  const withAuthClient = modules.filter((m) => m.hasAuthClient);
  const withAuditSink = modules.filter((m) => m.hasAuditSink);
  const withEvents = modules.filter((m) => m.hasEvents);
  const withSubscribers = modules.filter((m) => m.hasSubscribers);
  const withSlots = modules.filter((m) => m.hasSlots);
  const withClientSlots = modules.filter((m) => m.hasClientSlots);
  const loadersByLocale = locales.map((locale) => ({
    locale,
    loaders: modules
      .filter((m) => m.locales.includes(locale))
      .map((m) =>
        entry(
          m,
          `{ key: "${m.name}", load: () => import("@/features/${m.name}/i18n/${locale}.json").then((m) => m.default) }`,
        ),
      ),
  }));

  const serverImports = configImports(
    options,
    usedHelpers({
      applyGatoConfig: withModule.length > 0,
      enabledEntries:
        withEnv.length > 0 ||
        withAuth.length > 0 ||
        withAuditSink.length > 0 ||
        loadersByLocale.some(({ loaders }) => loaders.length > 0),
      enabledModuleEntries: withSubscribers.length > 0,
      gatoBrandingOf: false,
    }),
  );

  const server = [
    GENERATED_HEADER,
    serverImports.config,
    'import type { Locale } from "@/i18n/config";',
    'import { createEnv } from "@gatojs/env";',
    ...serverImports.helpers,
    `import { slotRegistry } from "${SLOTS_MODULE}";`,
    ...withModule.map(
      (m) =>
        `import ${identifier(m.name, "Module")} from "@/features/${m.name}/module";`,
    ),
    ...withEnv.map(
      (m) =>
        `import { envSchema as ${identifier(m.name, "EnvSchema")} } from "@/features/${m.name}/env";`,
    ),
    ...withAuth.map(
      (m) =>
        `import { authPlugin as ${identifier(m.name, "AuthPlugin")} } from "@/features/${m.name}/auth";`,
    ),
    ...withAuditSink.map(
      (m) =>
        `import { auditSink as ${identifier(m.name, "AuditSink")} } from "@/features/${m.name}/audit-sink";`,
    ),
    ...withEvents.map(
      (m) =>
        `import { events as ${identifier(m.name, "Events")} } from "@/features/${m.name}/events";`,
    ),
    ...withSubscribers.map(
      (m) =>
        `import { subscribers as ${identifier(m.name, "Subscribers")} } from "@/features/${m.name}/subscribers";`,
    ),
    ...withSlots.map(slotsImport),
    ...withClientSlots.map(clientSlotsImport),
    "",
    configuredModules(
      "modules",
      withModule.map((m) => identifier(m.name, "Module")),
    ),
    enabledList(
      "moduleEnvSchemas",
      withEnv.map((m) => entry(m, identifier(m.name, "EnvSchema"))),
    ),
    enabledList(
      "authPlugins",
      withAuth.map((m) => entry(m, identifier(m.name, "AuthPlugin"))),
    ),
    enabledList(
      "auditSinks",
      withAuditSink.map((m) => entry(m, identifier(m.name, "AuditSink"))),
    ),
    moduleEntries(
      "moduleEvents",
      withEvents.map((m) => entry(m, identifier(m.name, "Events"))),
    ),
    enabledModuleList(
      "moduleSubscribers",
      withSubscribers.map((m) => entry(m, identifier(m.name, "Subscribers"))),
    ),
    `export const moduleSlots = slotRegistry({ slots: ${slotEntries(withSlots, "Slots")}, clientSlots: ${slotEntries(withClientSlots, "ClientSlots")} }, gatoConfig);`,
    "export const env = createEnv(moduleEnvSchemas);",
    "",
    "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
    "",
    "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
    ...loadersByLocale.flatMap(({ locale, loaders }) =>
      loaders.length === 0
        ? [`  ${locale}: [],`]
        : [
            `  ${locale}: enabledEntries<MessageLoader>([`,
            ...loaders.map((l) => `    ${l},`),
            "  ], gatoConfig),",
          ],
    ),
    "};",
    "",
  ].join("\n");

  const clientImports = configImports(
    options,
    usedHelpers({
      applyGatoConfig: withModule.length > 0,
      enabledEntries: withAuthClient.length > 0,
      enabledModuleEntries: false,
      gatoBrandingOf: true,
    }),
  );

  const client = [
    GENERATED_HEADER,
    clientImports.config,
    ...clientImports.helpers,
    `import { clientSlotRegistry } from "${SLOTS_MODULE}";`,
    ...withAuthClient.map(
      (m) =>
        `import { authClientPlugin as ${identifier(m.name, "AuthClientPlugin")} } from "@/features/${m.name}/auth-client";`,
    ),
    ...withModule.map(
      (m) =>
        `import ${identifier(m.name, "Module")} from "@/features/${m.name}/module";`,
    ),
    ...withClientSlots.map(clientSlotsImport),
    "",
    enabledList(
      "authClientPlugins",
      withAuthClient.map((m) =>
        entry(m, identifier(m.name, "AuthClientPlugin")),
      ),
    ),
    configuredModules(
      "clientModules",
      withModule.map((m) => identifier(m.name, "Module")),
    ),
    `export const clientModuleSlots = clientSlotRegistry(${slotEntries(withClientSlots, "ClientSlots")}, gatoConfig);`,
    "export const gatoBranding = gatoBrandingOf(gatoConfig);",
    "",
  ].join("\n");

  return { server, client };
}
